 for(const app of apps)await app.close();await client?.close();if(repl)await repl.stop({doCleanup:false,force:false});process.stderr.write=originalStderr;report.runtimeWarnings=runtimeWarnings;report.gracefulMongoStopProven=!runtimeWarnings.some(x=>x.includes('SIGKILL'));report.serverMetadataCommitViaSyncVerified=report.cases.some(c=>c.id==='B033-commit-real-atomic-metadata-bytes-receipts-changes'&&c.status==='passed');report.cleanup.push({ownedMongoStopRequested:!!repl,dataAndBytesRetained:runtime});report.counts=Object.fromEntries(['passed','failed'].map(s=>[s,report.cases.filter(c=>c.status===s).length]));report.sources={};report.sourcesUnchangedDuringRun=true;
 for(const[p,b]of sources){report.sources[p.replaceAll('\\','/')]=sha(b);if(sha(await readFile(p))!==sha(b))report.sourcesUnchangedDuringRun=false;const dest=path.join(out,'sources',p);await mkdir(path.dirname(dest),{recursive:true});await writeFile(dest,b,{flag:'wx'});}if(!report.sourcesUnchangedDuringRun)report.fatal='Source changed during run';await writeFile(out+'/results.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});
 const hashes={};async function scan(dir){for(const f of await readdir(dir,{withFileTypes:true})){const p=path.join(dir,f.name);if(f.isDirectory())await scan(p);else hashes[path.relative(out,p).replaceAll('\\','/')]=sha(await readFile(p));}}await scan(out);await writeFile(out+'/hashes.json',JSON.stringify(hashes,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({out,counts:report.counts,fatal:report.fatal}));if(report.fatal||report.counts.failed||!report.cases.length)process.exitCode=1;
